-- 040 · Krueka Crea: proyectos privados, versiones, recursos y revisión
-- El acceso infantil exige alumno activo de B.E.I. y dispositivo vinculado.

create table public.club_creator_projects (
 id uuid primary key default gen_random_uuid(),student_id uuid not null references public.club_students(id) on delete cascade,institution_id uuid not null references public.institutions(id) on delete cascade,
 type text not null check(type in('game','web','design')),title text not null check(char_length(title) between 1 and 80),content jsonb not null default '{}'::jsonb check(jsonb_typeof(content)='object'),status text not null default 'draft' check(status in('draft','review','published','archived')),version integer not null default 1 check(version>0),
 review_note text check(review_note is null or char_length(review_note)<=500),reviewed_by uuid references public.profiles(id) on delete set null,reviewed_at timestamptz,published_at timestamptz,last_saved_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.club_creator_versions (
 id bigint generated always as identity primary key,project_id uuid not null references public.club_creator_projects(id) on delete cascade,student_id uuid not null references public.club_students(id) on delete cascade,version integer not null check(version>0),title text not null check(char_length(title) between 1 and 80),content jsonb not null check(jsonb_typeof(content)='object'),created_at timestamptz not null default now(),unique(project_id,version)
);
create table public.club_creator_assets (
 id uuid primary key default gen_random_uuid(),student_id uuid not null references public.club_students(id) on delete cascade,project_id uuid references public.club_creator_projects(id) on delete cascade,kind text not null check(kind in('sprite','background','sound','palette')),name text not null check(char_length(name) between 1 and 60),definition jsonb not null default '{}'::jsonb check(jsonb_typeof(definition)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.club_creator_templates (
 slug text primary key check(slug~'^[a-z0-9-]{3,50}$'),type text not null check(type in('game','web','design')),level text not null default 'all' check(level in('all','peques','mayores')),title text not null check(char_length(title) between 1 and 80),description text not null default '' check(char_length(description)<=240),content jsonb not null default '{}'::jsonb check(jsonb_typeof(content)='object'),active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
comment on table public.club_creator_projects is 'Proyectos privados creados por estudiantes del Club en Krueka Crea.';
comment on table public.club_creator_versions is 'Historial acotado de versiones de cada proyecto creativo.';
comment on table public.club_creator_assets is 'Recursos creativos estructurados: sprites, fondos, sonidos y paletas.';
comment on table public.club_creator_templates is 'Plantillas aprobadas por el equipo para iniciar proyectos sin recursos externos.';
create index club_creator_projects_student_updated_idx on public.club_creator_projects(student_id,updated_at desc) where status<>'archived';
create index club_creator_projects_institution_status_idx on public.club_creator_projects(institution_id,status,updated_at desc);
create index club_creator_projects_reviewed_by_idx on public.club_creator_projects(reviewed_by) where reviewed_by is not null;
create index club_creator_versions_project_idx on public.club_creator_versions(project_id,version desc);
create index club_creator_versions_student_idx on public.club_creator_versions(student_id);
create index club_creator_assets_student_idx on public.club_creator_assets(student_id,updated_at desc);
create index club_creator_assets_project_idx on public.club_creator_assets(project_id) where project_id is not null;
create index club_creator_templates_active_idx on public.club_creator_templates(active,level,type,sort_order);
alter table public.club_creator_projects enable row level security;alter table public.club_creator_projects force row level security;
alter table public.club_creator_versions enable row level security;alter table public.club_creator_versions force row level security;
alter table public.club_creator_assets enable row level security;alter table public.club_creator_assets force row level security;
alter table public.club_creator_templates enable row level security;alter table public.club_creator_templates force row level security;
revoke all on table public.club_creator_projects from public,anon,authenticated;revoke all on table public.club_creator_versions from public,anon,authenticated;revoke all on table public.club_creator_assets from public,anon,authenticated;revoke all on table public.club_creator_templates from public,anon,authenticated;revoke all on sequence public.club_creator_versions_id_seq from public,anon,authenticated;
insert into public.club_creator_templates(slug,type,level,title,description,content,sort_order) values
('game-stars','game','peques','Atrapa las estrellas','Mover, sumar puntos y ganar.',jsonb_build_object('jugador','🚀','premio','⭐','meta',5),10),
